-- Structure fingerprint of schema public (hashes and counts only): run on the source and on the restored copy,
-- the two outputs must be equal. Functions that belong to extensions are left out. Usage: psql "$DB" -X -At -F '	' -v ON_ERROR_STOP=1 -f scripts/backup-structure.sql
select 'tables', count(*)::text from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')
union all select 'columns', md5(string_agg(table_name||':'||column_name||':'||data_type||':'||coalesce(column_default,'')||':'||is_nullable||':'||is_identity||':'||is_generated,'|' order by table_name,ordinal_position)) from information_schema.columns where table_schema='public'
union all select 'constraints', count(*)||' '||md5(string_agg(conrelid::regclass::text||':'||conname||':'||pg_get_constraintdef(k.oid),'|' order by conrelid::regclass::text,conname)) from pg_constraint k join pg_namespace n on n.oid=k.connamespace where n.nspname='public'
union all select 'indexes', count(*)||' '||md5(string_agg(indexdef,'|' order by indexname)) from pg_indexes where schemaname='public'
union all select 'functions', count(*)||' '||md5(string_agg(replace(pg_get_functiondef(p.oid),chr(13),''),'|' order by p.oid::regprocedure::text)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind in ('f','p') and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
union all select 'function_grants', md5(coalesce(string_agg(x,'|' order by x),'')) from (select p.oid::regprocedure::text||':'||pg_get_userbyid(a.grantee)||':'||a.privilege_type x from pg_proc p join pg_namespace n on n.oid=p.pronamespace, aclexplode(p.proacl) a where n.nspname='public' and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')) s
union all select 'triggers', count(*)||' '||md5(string_agg(pg_get_triggerdef(t.oid),'|' order by c.relname,t.tgname)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and not t.tgisinternal
union all select 'rls', string_agg(c.relname||'='||c.relrowsecurity::text||'/'||c.relforcerowsecurity::text, ',' order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p')
union all select 'policies', count(*)||' '||md5(string_agg(c.relname||':'||p.polname||':'||p.polcmd::text||':'||p.polpermissive::text||':'||p.polroles::regrole[]::text||':'||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||':'||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),'|' order by c.relname,p.polname)) from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'
union all select 'table_grants', md5(coalesce(string_agg(x,'|' order by x),'')) from (select c.relname||':'||pg_get_userbyid(a.grantee)||':'||a.privilege_type x from pg_class c join pg_namespace n on n.oid=c.relnamespace, aclexplode(c.relacl) a where n.nspname='public') s
union all select 'column_grants', md5(coalesce(string_agg(x,'|' order by x),'')) from (select c.relname||'.'||att.attname||':'||pg_get_userbyid(a.grantee)||':'||a.privilege_type x from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute att on att.attrelid=c.oid and att.attnum>0 and not att.attisdropped, aclexplode(att.attacl) a where n.nspname='public') s
union all select 'realtime', coalesce(string_agg(tablename, ',' order by tablename),'') from pg_publication_tables where pubname='supabase_realtime' and schemaname='public';
